// Stage 1 Validation: Collect & Validate Requirements
const body = $input.first().json.body || $input.first().json;

if (!body.projectName || !body.repoDetails || !body.repoDetails.url) {
  throw new Error('Validation Failed: Project name and repository URL are required.');
}

const requestId = body.id || `REQ-2026-${Math.floor(1000 + Math.random() * 9000)}`;
const accountType = body.accountType || 'development';

return [{
  json: {
    requestId,
    developer: body.submittedBy || { name: 'Alex Rivera', email: 'alex@dev.internal', role: 'developer' },
    projectName: body.projectName,
    template: body.template || 'nextjs-saas',
    repoUrl: body.repoDetails.url,
    branch: body.repoDetails.branch || 'main',
    sandboxType: body.sandboxType || 'isolated-container',
    accountType,
    developmentPurpose: body.developmentPurpose || 'feature_development',
    requestedTools: body.requestedTools || ['Node.js 20', 'Docker Engine'],
    requestedPermissions: body.requestedPermissions || ['read_code', 'write_sandbox'],
    sampleDataRequirement: body.sampleDataRequirement || 'synthetic_customers',
    isProductionTarget: accountType === 'production',
    collectedAt: new Date().toISOString()
  }
}];

// Stage 2: Discover Resources (Mock Repository & Active Sandbox Registry)
const item = $input.first().json;

// Query mock active sandbox registry for anti-duplication (Rule POL-003)
const activeRegistry = {
  'github.com/agentic-hackathon/analytics-service:main': {
    sandboxId: 'sbx-worker-existing-09',
    port: 8089,
    status: 'ACTIVE'
  }
};

const cleanKey = item.repoUrl.replace(/^https?:\/\//, '') + ':' + item.branch;
const existing = activeRegistry[cleanKey];

return [{
  json: {
    ...item,
    discovery: {
      repoAvailable: true,
      targetCommitHash: '8b7d12f',
      existingSandboxFound: !!existing,
      existingSandboxId: existing ? existing.sandboxId : null,
      existingPort: existing ? existing.port : null,
      discoveryStatus: 'COMPLETED'
    }
  }
}];

parameters.prompt:
You are the AI Agent Architect for the Developer Sandbox Bootstrapper (Agentic AI Hackathon 2026).

Analyze this validated setup request and generate a structured JSON setup plan following least-privilege principles:

Project: {{$json.projectName}}
Template: {{$json.template}}
Repo: {{$json.repoUrl}} @ {{$json.branch}}
Account Target: {{$json.accountType}}
Requested Permissions: {{$json.requestedPermissions.join(', ')}}
Sample Data: {{$json.sampleDataRequirement}}
Existing Sandbox Detected: {{$json.discovery.existingSandboxFound ? 'YES - ' + $json.discovery.existingSandboxId : 'NO (Fresh allocation needed)'}}

SECURITY CONSTRAINTS:
1. If accountType is 'production', flag critical security block (POL-001).
2. Strip wildcards ('*') and live production database privileges (POL-002).
3. If existing sandbox is present, reuse it without creating duplicate containers (POL-003).
4. Mandate purely synthetic seed data; prohibit real customer PII (POL-004).

Return strict JSON matching the schema with planVersion, orderedSteps, minimumNecessaryPermissions, strippedPermissions, and risks.

parameters.jsCode:
// Stage 4: Deterministic Backend Security Validation
// Never allow AI-generated text alone to authorize sandbox creation.
const item = $input.first().json;

// Policy POL-001: Never create a sandbox for a production account
if (item.accountType === 'production' || item.isProductionTarget) {
  return [{
    json: {
      ...item,
      securityStatus: 'BLOCKED',
      blockedRule: 'POL-001',
      blockedReason: 'SAFETY REQUIREMENT ENFORCEMENT: Never create a sandbox for a production account.',
      nextAction: 'HALT_WORKFLOW'
    }
  }];
}

// Policy POL-002: Least Privilege Enforcement
const granted = [];
const stripped = [];

for (const perm of item.requestedPermissions) {
  if (perm.includes('*') || perm === 'access_production_db' || perm === 'admin_cluster') {
    stripped.push(perm);
  } else {
    granted.push(perm);
  }
}
if (!granted.includes('read_code')) granted.push('read_code');
if (!granted.includes('write_sandbox')) granted.push('write_sandbox');

return [{
  json: {
    ...item,
    securityStatus: 'PASSED',
    grantedPermissions: granted,
    strippedPermissions: stripped,
    nextAction: 'REQUEST_HUMAN_APPROVAL'
  }
}];

// Stage 5: Human Approval Gate
// Pauses execution and registers pending approval on Administrator Dashboard
const item = $input.first().json;

return [{
  json: {
    ...item,
    approvalStatus: 'AWAITING_ADMIN_SIGN_OFF',
    reviewPrompt: 'Administrator must review least-privilege bounds and sign plan before execution.'
  }
}];

// Stage 6: Execute Approved Setup (Mock Container Provision / Reuse)
const item = $input.first().json;
const isReused = item.discovery && item.discovery.existingSandboxFound;
const sandboxId = isReused ? item.discovery.existingSandboxId : `sbx-${item.projectName.slice(0, 10)}-${Math.floor(100 + Math.random() * 900)}`;
const port = isReused ? item.discovery.existingPort : Math.floor(8100 + Math.random() * 500);

return [{
  json: {
    ...item,
    execution: {
      sandboxId,
      port,
      endpointUrl: `http://localhost:${port}`,
      reusedExisting: isReused,
      status: 'SUCCESS',
      syntheticRecordsSeeded: 50
    }
  }
}];

// Stage 7: Run Smoke Login Test
const item = $input.first().json;
const endpoint = item.execution.endpointUrl + '/api/mock-auth/login';

return [{
  json: {
    ...item,
    smokeTest: {
      status: 'PASSED',
      responseStatusCode: 200,
      latencyMs: 16,
      loginEndpoint: endpoint,
      tokenPreview: 'sbx_jwt_eyJhbGciOi...[REDACTED_MOCK_BEARER]',
      verifiedAt: new Date().toISOString()
    }
  }
}];

// Stage 8: Generate Setup Manifest (Secret Redaction & SHA-256 Seal)
const crypto = require('crypto');
const item = $input.first().json;

const rawConfig = {
  NODE_ENV: 'development-sandbox',
  PORT: String(item.execution.port),
  CONTAINER_ID: item.execution.sandboxId,
  STRIPE_SECRET: '[REDACTED_STRIPE_TEST_KEY]',
  GITHUB_PAT: '[REDACTED_GITHUB_PAT]'
};

const manifestId = `MNF-${item.requestId.replace('REQ-', '')}`;
const sha256 = crypto.createHash('sha256').update(JSON.stringify(rawConfig)).digest('hex');

return [{
  json: {
    ...item,
    manifest: {
      manifestId,
      sha256Hash: sha256,
      sanitizedConfig: rawConfig,
      complianceScore: '100% Verified (Zero Secrets Exposed)',
      sealedAt: new Date().toISOString()
    }
  }
}];
